"""Validate and index the plan's local holiday dates."""

import datetime as dt
from bisect import bisect_right

from .errors import PlanError
from .rules import parse_date

LAST_ORDINAL = dt.date.max.toordinal()


class Holidays:
    def __init__(self, entries):
        if not isinstance(entries, list):
            raise PlanError("plan holidays must be a list")
        ranges = []
        for index, entry in enumerate(entries):
            parts = entry.split("..", 1) if isinstance(entry, str) else []
            dates = [parse_date(part) for part in parts]
            if not dates or None in dates or dates[0] > dates[-1]:
                raise PlanError(f"holiday #{index} must be a date or an inclusive date range")
            ranges.append((dates[0].toordinal(), dates[-1].toordinal()))

        self.ranges = []
        for first, last in sorted(ranges):
            if self.ranges and first <= self.ranges[-1][1] + 1:
                previous_first, previous_last = self.ranges[-1]
                self.ranges[-1] = (previous_first, max(previous_last, last))
            else:
                self.ranges.append((first, last))

    def containing(self, ordinal):
        index = bisect_right(self.ranges, (ordinal, LAST_ORDINAL))
        if index and ordinal <= self.ranges[index - 1][1]:
            return self.ranges[index - 1]
        return None

    def partition(self, first, last):
        """Yield inclusive ordinal intervals and the full holiday range for each."""
        index = bisect_right(self.ranges, (first, LAST_ORDINAL))
        if index and first <= self.ranges[index - 1][1]:
            index -= 1
        while index < len(self.ranges) and self.ranges[index][0] <= last:
            block_first, block_last = self.ranges[index]
            if first < block_first:
                yield first, block_first - 1, None
            yield max(first, block_first), min(last, block_last), self.ranges[index]
            first = block_last + 1
            index += 1
        if first <= last:
            yield first, last, None
"""Turn one rule into concrete occurrences (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass
from functools import lru_cache
from math import gcd
from typing import TYPE_CHECKING

from .errors import PlanError
from .holidays import LAST_ORDINAL
from .rules import ELAPSED_MINUTES, parse_local

if TYPE_CHECKING:
    from .plan import RuleDef

DAY_SECONDS = 86400
EPOCH = dt.datetime.min
LAST_SECOND = LAST_ORDINAL * DAY_SECONDS - 1


@dataclass
class Occurrence:
    rule: "RuleDef"
    key: str
    start: int   # UTC seconds since 0001-01-01
    end: int


def instant(value):
    """Return the UTC instant as an integer, including at calendar boundaries."""
    days = value.toordinal() - 1
    seconds = value.hour * 3600 + value.minute * 60 + value.second
    offset = value.utcoffset()
    return days * DAY_SECONDS + seconds - (offset.days * DAY_SECONDS + offset.seconds)


def local_instant(value, zone):
    # fold=0 takes the pre-transition offset in both a fold and a gap.
    return instant(value.replace(tzinfo=zone, fold=0))


def utc_date(seconds):
    ordinal = seconds // DAY_SECONDS + 1
    return dt.date.fromordinal(min(max(ordinal, 1), LAST_ORDINAL))


def _local_time(seconds, zone):
    # UTC can lie just outside datetime's calendar while the local date is inside it.
    reference = min(max(seconds, 0), LAST_SECOND)
    utc = EPOCH + dt.timedelta(seconds=reference)
    local = zone.fromutc(utc.replace(tzinfo=zone))
    if seconds != reference:
        local = local.replace(tzinfo=dt.timezone(local.utcoffset()))
        local += dt.timedelta(seconds=seconds - reference)
    return local


@lru_cache(maxsize=8192)
def _local_ordinal(seconds, zone):
    try:
        return _local_time(seconds, zone).toordinal()
    except OverflowError:
        # Date filters can compare out-of-range local dates without rendering them.
        return 0 if seconds < DAY_SECONDS else LAST_ORDINAL + 1


def timestamp(seconds, ruledef):
    try:
        return _format_timestamp(seconds, ruledef.tz)
    except OverflowError:
        raise PlanError(f"rule {ruledef.id}: timestamp is outside the four-digit calendar") from None


@lru_cache(maxsize=8192)
def _format_timestamp(seconds, zone):
    local = _local_time(seconds, zone)
    offset_seconds = int(local.utcoffset().total_seconds())
    # Preserve historical offset seconds in instant arithmetic, then render ±HH:MM.
    hours, minutes = divmod(abs(offset_seconds) // 60, 60)
    sign = "-" if offset_seconds < 0 else "+"
    return f"{local.isoformat(timespec='seconds')[:19]}{sign}{hours:02d}:{minutes:02d}"


def _aligned(anchor, first, stride):
    """First point in the recurrence at or after first."""
    return anchor + ((first - anchor + stride - 1) // stride) * stride


def _candidate_dates(rule, first, last):
    first = max(first, rule.start)
    if rule.until is not None:
        last = min(last, rule.until)
    if first > last:
        return

    lo, hi = first.toordinal(), last.toordinal()
    anchor = rule.start.toordinal()
    if rule.unit == "day":
        for ordinal in range(_aligned(anchor, lo, rule.every), hi + 1, rule.every):
            yield dt.date.fromordinal(ordinal)
    elif rule.unit == "week":
        anchor -= rule.start.weekday()
        stride = rule.every * 7
        for monday in range(_aligned(anchor, lo - first.weekday(), stride), hi + 1, stride):
            for weekday in rule.on:
                ordinal = monday + weekday
                if lo <= ordinal <= hi:
                    yield dt.date.fromordinal(ordinal)
    else:
        anchor = rule.start.year * 12 + rule.start.month - 1
        first_month = first.year * 12 + first.month - 1
        last_month = last.year * 12 + last.month - 1
        # Month lengths repeat every 400 years, including along the rule's stride.
        cycle = 4800 // gcd(rule.every, 4800)
        empty_months = 0
        for index in range(_aligned(anchor, first_month, rule.every), last_month + 1, rule.every):
            year, month = divmod(index, 12)
            month += 1
            month_len = calendar.monthrange(year, month)[1]
            days = {month_len if item == "last" else item for item in rule.on}
            valid_days = sorted(day for day in days if day <= month_len)
            if not valid_days:
                empty_months += 1
                if empty_months == cycle:
                    break
                continue
            empty_months = 0
            for day in valid_days:
                date = dt.date(year, month, day)
                if first <= date <= last:
                    yield date


def _starts_on(ruledef, day):
    seen = set()
    for time in ruledef.rule.at:
        local = dt.datetime.combine(day, time)
        start = local_instant(local, ruledef.tz)
        if start not in seen:
            seen.add(start)
            yield time, start


def _calendar_key(day, time):
    return dt.datetime.combine(day, time).isoformat(timespec="minutes")


def _regular_starts(ruledef, first, last):
    for day in _candidate_dates(ruledef.rule, first, last):
        for time, start in _starts_on(ruledef, day):
            yield _calendar_key(day, time), start


def _shifted_starts(ruledef, first, last, block):
    block_first, block_last = block
    target = dt.date.fromordinal(min(block_last + 1, LAST_ORDINAL))
    # A holiday ending on the last representable date shifts into the next year.
    outside_calendar = block_last == LAST_ORDINAL
    available = set(ruledef.rule.at)
    if not outside_calendar and next(_candidate_dates(ruledef.rule, target, target), None):
        available.difference_update(time for time, _ in _starts_on(ruledef, target))
    if not available:
        return

    # A whole consecutive holiday block shares one destination. Start at the
    # block's first candidate so an earlier key can claim each available time.
    for day in _candidate_dates(ruledef.rule, dt.date.fromordinal(block_first), last):
        for time, _ in _starts_on(ruledef, day):
            if time in available:
                available.remove(time)
                if day >= first:
                    start = local_instant(dt.datetime.combine(target, time), ruledef.tz)
                    if outside_calendar:
                        start += DAY_SECONDS
                    yield _calendar_key(day, time), start
        if not available:
            break


def _calendar_starts(ruledef, holidays, first, last):
    rule = ruledef.rule
    first = max(first, rule.start)
    if rule.until is not None:
        last = min(last, rule.until)
    if first > last:
        return
    if ruledef.holiday == "keep" or not holidays.ranges:
        yield from _regular_starts(ruledef, first, last)
        return
    for lo, hi, block in holidays.partition(first.toordinal(), last.toordinal()):
        start, end = dt.date.fromordinal(lo), dt.date.fromordinal(hi)
        if block is None:
            yield from _regular_starts(ruledef, start, end)
        elif ruledef.holiday == "shift":
            yield from _shifted_starts(ruledef, start, end, block)


def _elapsed_anchor(ruledef):
    rule = ruledef.rule
    return local_instant(dt.datetime.combine(rule.start, rule.start_time), ruledef.tz)


def _elapsed_starts(ruledef, holidays, first, last):
    rule = ruledef.rule
    anchor = _elapsed_anchor(ruledef)
    stride = rule.every * ELAPSED_MINUTES[rule.unit] * 60
    first = anchor if first is None else _aligned(anchor, max(first, anchor), stride)
    skip_holidays = ruledef.holiday == "skip" and holidays.ranges
    if rule.until is None and not skip_holidays:
        yield from range(first, last + 1, stride)
        return
    until = rule.until.toordinal() if rule.until is not None else None
    if until is not None:
        last = min(last, (until + 1) * DAY_SECONDS - 1)

    start = first
    while start <= last:
        day = _local_ordinal(start, ruledef.tz)
        block = holidays.containing(day) if skip_holidays else None
        if block is None and (until is None or day <= until):
            yield start
        if block is not None and start >= block[0] * DAY_SECONDS:
            # Only jump over instants whose local dates remain in this block
            # even if the offset changes. Inspect the dates at both edges.
            start = _aligned(anchor, max(start + stride, (block[1] - 1) * DAY_SECONDS), stride)
        else:
            start += stride


@lru_cache(maxsize=8192)
def _utc_key(start):
    if 0 <= start <= LAST_SECOND:
        return (EPOCH + dt.timedelta(seconds=start)).isoformat(timespec="minutes") + "Z"
    return None


def _elapsed_pairs(ruledef, holidays, first, last):
    for start in _elapsed_starts(ruledef, holidays, first, last):
        yield _utc_key(start), start


def has_candidate(ruledef, holidays, key):
    elapsed = ruledef.rule.start_time is not None
    if elapsed and not key.endswith("Z"):
        return False
    local = parse_local(key[:-1] if elapsed else key)
    if local is None:
        return False
    if elapsed:
        minute = instant(local.replace(tzinfo=dt.timezone.utc))
        return next(_elapsed_starts(ruledef, holidays, minute, minute + 59), None) is not None
    day = local.date()
    return any(candidate == key for candidate, _ in _calendar_starts(ruledef, holidays, day, day))


def _counted(candidates, limit):
    for count, candidate in enumerate(candidates, 1):
        yield candidate
        if count == limit:
            return


def counted_keys(ruledef, holidays, last_key):
    """Yield keys through the count limit, searching only up to the last override key."""
    rule = ruledef.rule
    if rule.start_time is None:
        last = dt.date.fromisoformat(last_key[:10])
        candidates = _calendar_starts(ruledef, holidays, rule.start, last)
    else:
        last = parse_local(last_key[:-1]).replace(tzinfo=dt.timezone.utc)
        candidates = _elapsed_pairs(ruledef, holidays, None, instant(last) + 59)
    for key, _ in _counted(candidates, rule.times):
        yield key


def expand(ruledef, holidays, first, last):
    """Yield surviving base occurrences with start instants in the inclusive range."""
    rule = ruledef.rule
    if rule.start_time is not None:
        search_start = first if rule.times is None else None
        candidates = _elapsed_pairs(ruledef, holidays, search_start, last)
    else:
        # Nominal wall times may differ from their UTC instants by up to a day.
        first_day = utc_date(first - DAY_SECONDS)
        last_day = utc_date(last + DAY_SECONDS)
        if rule.times is not None:
            first_day = rule.start
        elif ruledef.holiday == "shift":
            earlier_block = holidays.containing(first_day.toordinal() - 1)
            if earlier_block is not None:
                first_day = dt.date.fromordinal(earlier_block[0])
        candidates = _calendar_starts(ruledef, holidays, first_day, last_day)

    length = rule.minutes * 60
    for key, start in _counted(candidates, rule.times):
        if first <= start <= last:
            if key is None:
                raise PlanError(f"rule {ruledef.id}: UTC key is outside the four-digit calendar")
            yield Occurrence(ruledef, key, start, start + length)
"""Plan loading (SPEC.md sections 1 and 5)."""

import re
from dataclasses import dataclass
from functools import cache
from typing import Optional
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError, available_timezones

from .errors import PlanError, RuleSyntaxError
from .expand import Occurrence, counted_keys, has_candidate, local_instant
from .holidays import Holidays
from .rules import DATE_PATTERN, Rule, parse_duration, parse_local, parse_rule


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: ZoneInfo
    priority: int
    holiday: str


@dataclass
class Plan:
    rules: list[RuleDef]
    overrides: dict[str, dict[str, Optional[Occurrence]]]  # None means cancel
    min_segment: int
    holidays: Holidays


@cache
def _zone_names():
    # ZoneInfo can open differently cased paths on case-insensitive filesystems.
    return available_timezones()


def _zone(name, context):
    if not isinstance(name, str):
        raise PlanError(f"{context}: timezone must be a string")
    if name in _zone_names():
        try:
            return ZoneInfo(name)
        except (ValueError, ZoneInfoNotFoundError):
            pass
    raise PlanError(f"{context}: unknown timezone {name!r}")


def _load_rules(items, default_tz):
    if not isinstance(items, list):
        raise PlanError("plan rules must be a list")
    rules = {}
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            raise PlanError(f"rule #{index} must be an object")
        rid = item.get("id")
        if not isinstance(rid, str):
            raise PlanError(f"rule #{index} needs a string id")
        if not re.fullmatch(r"[A-Za-z0-9_-]+", rid):
            raise PlanError(f"rule #{index} has invalid id {rid!r}")
        if rid in rules:
            raise PlanError(f"duplicate rule id {rid!r}")
        source = item.get("rule")
        if not isinstance(source, str):
            raise PlanError(f"rule {rid}: rule text must be a string")
        try:
            rule = parse_rule(source)
        except RuleSyntaxError as exc:
            raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, source) from None
        zone = _zone(item["timezone"], f"rule {rid}") if "timezone" in item else default_tz
        priority = item.get("priority", 0)
        if type(priority) is not int:
            raise PlanError(f"rule {rid}: priority must be an integer")
        holiday = item.get("holiday", "keep")
        if holiday not in ("keep", "skip", "shift"):
            raise PlanError(f"rule {rid}: holiday must be 'keep', 'skip' or 'shift'")
        if holiday == "shift" and rule.start_time is not None:
            raise PlanError(f"rule {rid}: minute and hour rules cannot shift for holidays")
        rules[rid] = RuleDef(index, rid, rule, zone, priority, holiday)
    return rules


def _duration(raw, context):
    minutes = parse_duration(raw)
    if minutes is None:
        raise PlanError(f"{context}: invalid duration")
    return minutes


def _override_key(raw, ruledef, holidays):
    if not isinstance(raw, str):
        raise PlanError(f"rule {ruledef.id}: override key must be a string")
    if len(ruledef.rule.at) == 1 and re.fullmatch(DATE_PATTERN, raw):
        raw = f"{raw}T{ruledef.rule.at[0].isoformat(timespec='minutes')}"
    if not has_candidate(ruledef, holidays, raw):
        raise PlanError(f"rule {ruledef.id}: invalid override key {raw!r}")
    return raw


def _load_overrides(items, rules, holidays):
    if not isinstance(items, list):
        raise PlanError("plan overrides must be a list")
    overrides = {}
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            raise PlanError(f"override #{index} must be an object")
        rid = item.get("rule")
        if not isinstance(rid, str):
            raise PlanError(f"override #{index} needs a string rule id")
        if rid not in rules:
            raise PlanError(f"override for unknown rule {rid!r}")
        ruledef = rules[rid]
        key = _override_key(item.get("key"), ruledef, holidays)
        entries = overrides.setdefault(rid, {})
        if key in entries:
            raise PlanError(f"rule {rid}: duplicate override for {key}")

        action = item.get("action")
        if action == "cancel":
            entries[key] = None
        elif action == "move":
            local = parse_local(item.get("to"))
            if local is None:
                raise PlanError(f"rule {rid}: move override needs a valid 'to'")
            minutes = ruledef.rule.minutes
            if "for" in item:
                minutes = _duration(item["for"], f"rule {rid} override 'for'")
            start = local_instant(local, ruledef.tz)
            entries[key] = Occurrence(ruledef, key, start, start + minutes * 60)
        else:
            raise PlanError(f"rule {rid}: override action must be 'cancel' or 'move'")

    for rid, entries in overrides.items():
        ruledef = rules[rid]
        if ruledef.rule.times is None:
            continue
        remaining = set(entries)
        for key in counted_keys(ruledef, holidays, max(remaining)):
            remaining.discard(key)
            if not remaining:
                break
        if remaining:
            raise PlanError(f"rule {rid}: override key {min(remaining)} is past the occurrence count")
    return overrides


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    if "rules" not in raw:
        raise PlanError("plan has no rules")
    default_tz = _zone(raw["timezone"], "plan")
    rules = _load_rules(raw["rules"], default_tz)
    holidays = Holidays(raw.get("holidays", []))
    overrides = _load_overrides(raw.get("overrides", []), rules, holidays)
    min_segment = _duration(raw["min_segment"], "min_segment") if "min_segment" in raw else 0
    return Plan(list(rules.values()), overrides, min_segment, holidays)
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import datetime as dt
import heapq
import re

from .errors import PlanError
from .expand import expand, instant, timestamp
from .plan import load_plan
from .rules import DATE_PATTERN, TIME_PATTERN

BOUND_PATTERN = re.compile(rf"{DATE_PATTERN}T{TIME_PATTERN}(?::[0-5][0-9])?(?:Z|[+-]{TIME_PATTERN})")


def _parse_bound(text):
    if not isinstance(text, str):
        raise PlanError("query bounds must be strings")
    if BOUND_PATTERN.fullmatch(text):
        try:
            return instant(dt.datetime.fromisoformat(text.replace("Z", "+00:00")))
        except ValueError:
            pass
    raise PlanError(f"invalid date-time {text!r}")


def _overlaps(occ, start, end):
    return occ.start < end and occ.end > start


def _collect(plan, start, end):
    found = []
    for ruledef in plan.rules:
        overrides = plan.overrides.get(ruledef.id, {})
        # A base occurrence overlaps when its start is in this inclusive range.
        first = start - ruledef.rule.minutes * 60 + 1
        found.extend(occ for occ in expand(ruledef, plan.holidays, first, end - 1)
                     if occ.key not in overrides)
        found.extend(occ for occ in overrides.values()
                     if occ is not None and _overlaps(occ, start, end))
    return found


def _as_dict(occ, start, end):
    return {
        "rule": occ.rule.id,
        "key": occ.key,
        "start": timestamp(start, occ.rule),
        "end": timestamp(end, occ.rule),
    }


def _query(plan, start, end):
    plan = load_plan(plan)
    lo, hi = _parse_bound(start), _parse_bound(end)
    if hi <= lo:
        raise PlanError("end must be after start")
    return _collect(plan, lo, hi), lo, hi, plan.min_segment * 60


def occurrences(plan, start, end):
    rows, _, _, _ = _query(plan, start, end)
    rows.sort(key=lambda occ: (occ.start, occ.end, -occ.rule.priority, occ.rule.index, occ.key))
    return [_as_dict(occ, occ.start, occ.end) for occ in rows]


def _rank(occ):
    return -occ.rule.priority, occ.start, occ.rule.index, occ.key


def _segments(rows):
    """Yield each maximal interval during which the same occurrence wins."""
    starting = sorted(rows, key=lambda occ: occ.start)
    boundaries = sorted({point for occ in rows for point in (occ.start, occ.end)})
    active = []
    index = 0
    winner = None
    segment_start = None
    for point in boundaries:
        while index < len(starting) and starting[index].start == point:
            occ = starting[index]
            heapq.heappush(active, (_rank(occ), occ))
            index += 1
        while active and active[0][1].end <= point:
            heapq.heappop(active)
        next_winner = active[0][1] if active else None
        if winner is not next_winner:
            if winner is not None:
                yield winner, segment_start, point
            winner, segment_start = next_winner, point


def agenda(plan, start, end):
    rows, lo, hi, min_segment = _query(plan, start, end)
    result = []
    for occ, first, last in _segments(rows):
        lost_time = first > occ.start or last < occ.end
        if lost_time and last - first < min_segment:
            continue
        first, last = max(first, lo), min(last, hi)
        if first < last:
            result.append(_as_dict(occ, first, last))
    return result

import json
import sys

from .errors import PlanError, RuleSyntaxError
from .query import agenda, occurrences
from .rules import canonical, decimal_integer


def _invalid_json_constant(word):
    raise ValueError(f"invalid JSON constant {word}")


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) == 2 and argv[0] == "canonical":
        try:
            print(canonical(argv[1]))
        except PlanError as exc:
            return _report_plan_error(exc)
        return 0
    if len(argv) != 4 or argv[0] not in ("occurrences", "agenda"):
        print("usage: python3 -m cadence {occurrences,agenda} START END PLAN.json", file=sys.stderr)
        print("       python3 -m cadence canonical RULE", file=sys.stderr)
        return 1
    command, start, end, path = argv
    try:
        with open(path, "rb") as f:
            plan = json.load(f, parse_int=decimal_integer, parse_constant=_invalid_json_constant)
    except (OSError, ValueError, RecursionError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    query = occurrences if command == "occurrences" else agenda
    try:
        rows = query(plan, start, end)
    except PlanError as exc:
        return _report_plan_error(exc)
    if not rows:
        print("nothing scheduled")
    for row in rows:
        print(row["start"], row["end"], row["rule"], row["key"])
    return 0


def _report_plan_error(exc):
    print(f"error: {exc}", file=sys.stderr)
    if isinstance(exc, RuleSyntaxError):
        print(exc.text, file=sys.stderr)
        print(" " * exc.position + "^", file=sys.stderr)
    return 2
class PlanError(Exception):
    """Invalid plan, override or query argument."""


class RuleSyntaxError(PlanError):
    """Invalid rule text."""

    def __init__(self, message, position, text=None):
        super().__init__(message)
        self.position = position
        self.text = text
